<?php
namespace App\Filament\Resources\ReturnRequests\Pages;use App\Filament\Resources\ReturnRequests\ReturnRequestResource;use App\Services\StripeRefundService;use Filament\Actions\Action;use Filament\Forms\Components\TextInput;use Filament\Notifications\Notification;use Filament\Resources\Pages\EditRecord;class EditReturnRequest extends EditRecord{protected static string $resource=ReturnRequestResource::class;protected function getHeaderActions():array{return [Action::make('refund')->label('Reembolsar no Stripe')->color('danger')->requiresConfirmation()->schema([TextInput::make('amount')->label('Valor')->numeric()->prefix('€')->required()])->action(function(array $data){app(StripeRefundService::class)->refund($this->record,(float)$data['amount']);Notification::make()->title('Reembolso enviado ao Stripe')->success()->send();$this->refreshFormData(['status','refunded_amount','stripe_refund_id']);})->visible(fn()=>!in_array($this->record->status,['refunded','rejected']))];}}
